  locSynsHint: "\u043F\u0435\u0440\u0435\u0442\u0430\u0441\u043A\u0438\u0432\u0430\u0439\u0442\u0435 \u0437\u0430 \u0440\u0443\u0447\u043A\u0443 \u2014 \u043A\u0430\u0436\u0434\u044B\u0439 \u0438\u0434\u0451\u0442 \u0441\u0432\u043E\u0438\u043C \u0431\u043B\u043E\u043A\u043E\u043C \u0432 \xAB\u0410\u0441\u0441\u043E\u0446\u0438\u0430\u0446\u0438\u044F\u0445\xBB, \u0440\u044F\u0434\u043E\u043C \u0441 \u0430\u0441\u0441\u043E\u0446\u0438\u0430\u0446\u0438\u044F\u043C\u0438",
